function powerCopy(){return powerText[language];}
function powerButton(label,action,secondary=false){return button(label,action,secondary?'secondary':'primary');}
function stopPower(){clearTimeout(powerTimer);powerTimer=null;if(state.view==='power'&&state.stage===1){state.stage=0;state.count=0;}}
function renderPower(){const t=powerCopy();let html=activityHeader(t.badge)+'';
 if(state.view==='learn')return html+`<h1>${t.learn}</h1>${picture()}<p class="lead">${t.learnLead}</p><div class="actions">${powerButton(t.shield+' · '+t.shieldSub,'shield')}${powerButton(t.words,'words',true)}</div></div>`;
 if(state.view==='powers')return html+`<h1>${t.choose}</h1><p class="lead">${t.chooseLead}</p>${picture('tilo-respiracion.png')}<div class="actions">${powerButton(t.roar,'roar')}${powerButton(t.pause,'pause',true)}${powerButton(t.breath,'anger',true)}${powerButton(t.help,'support',true)}</div></div>`;
 if(state.view==='support')return html+`<h1>${t.support}</h1>${picture('tilo-mano.png')}<p class="message">${t.supportText}</p><div class="actions">${powerButton(t.home,'home')}${powerButton(t.other,'powers',true)}</div></div>`;
 if(state.view==='shield'){
 if(state.word>=shieldRounds.length)return html+`<h1>${t.finish}</h1>${picture('luma.png','Luma')}<p class="message">${t.finishText}</p><p>${t.limit}</p><div class="actions">${powerButton(t.again,'shield')}${powerButton(t.help,'support',true)}${powerButton(t.home,'home',true)}</div></div>`;
 const r=shieldRounds[state.word],right=state.wordChoice!==null&&state.wordChoice===r.fact;
 return html+`<h1>${t.shield}</h1>${picture('luma.png','Luma')}<p>${t.shieldIntro}</p><div class="original">${r[language]}</div><div class="actions">${powerButton(t.fact,'fact')}${powerButton(t.opinion,'opinion',true)}</div>${state.wordChoice!==null?`<p class="feedback" aria-live="polite">${right?(language==='es'?r.whyEs:r.whyEn):t.try}</p>${right?powerButton(t.next,'next-shield'):''}`:''}<p class="tiny">${t.round} ${state.word+1} / ${shieldRounds.length}</p></div>`;
 }
 if(state.view==='power'){
 const title=state.power==='roar'?t.roar:t.pause;
 if(state.stage===0)return html+`<h1>${title}</h1>${picture('tilo-respiracion.png')}<p class="message">${state.power==='roar'?t.roarIntro:t.pauseIntro}</p><p class="tiny">${t.comfort}</p><div class="actions">${powerButton(t.start,'start-power')}${powerButton(t.help,'support',true)}</div></div>`;
 if(state.stage===1)return html+`<h1>${title}</h1><p>${t.count}</p><div class="power-count" role="status" aria-live="polite">${state.count}</div><p>${state.power==='roar'?t.roarIntro:t.pauseIntro}</p><div class="actions">${powerButton(t.stop,'stop-power',true)}</div></div>`;
 return html+`<h1>${t.practice}</h1><p class="lead">${t.release}</p>${picture('tilo-respiracion.png')}<h2>${t.check}</h2><div class="actions">${powerButton(t.calmer,'power-calmer')}${powerButton(t.angry,'power-angry',true)}</div>${state.answer?`<p class="feedback" aria-live="polite">${state.answer==='yes'?t.yes:t.no}</p>`:''}<div class="actions">${powerButton(t.repeat,'repeat-power',true)}${powerButton(t.other,'powers',true)}${powerButton(t.help,'support',true)}${powerButton(t.home,'home',true)}</div>${state.power==='roar'?`<p><a class="video-link" href="https://www.youtube.com/watch?v=WbmCeu8nQBQ" target="_blank" rel="noopener noreferrer">▶ ${t.watch}</a></p><p class="tiny">${t.youtube}</p>`:''}</div>`;
 }
 return '';
}
function countPower(){if(state.view!=='power'||state.stage!==1||!state.running)return;powerTimer=setTimeout(()=>{if(state.view!=='power'||!state.running)return;if(state.count<5){state.count++;document.querySelector('.power-count').textContent=String(state.count);countPower();}else{state.stage=2;state.running=false;state.answer=null;render();}},1000);}
function handlePower(action){if(['learn','powers','shield','support'].includes(action)){open(action);return true;}if(['roar','pause'].includes(action)){open('power');state.power=action;render();return true;}if(action==='start-power'&&state.view==='power'&&state.stage===0){state.stage=1;state.count=1;state.running=true;render();countPower();return true;}if(action==='stop-power'&&state.view==='power'){stopTimers();state.stage=2;state.answer=null;render();return true;}if(action==='repeat-power'&&state.view==='power'){stopTimers();state.stage=0;state.answer=null;render();return true;}if(['power-calmer','power-angry'].includes(action)&&state.view==='power'){state.answer=action==='power-calmer'?'yes':'no';render();return true;}if(['fact','opinion'].includes(action)&&state.view==='shield'&&state.word<shieldRounds.length){state.wordChoice=action==='fact';render();return true;}if(action==='next-shield'&&state.view==='shield'&&state.wordChoice===shieldRounds[state.word]?.fact){state.word++;state.wordChoice=null;render();return true;}return false;}
